/bin/bash -lc "python - <<'PY'
import urllib.request
for vid,o,t in [('600725.0001',155812031,155812032),('600725.0002',155811824,155811825),('600725.0015',155811859,155811860)]:
 url=f'https://genome.ucsc.edu/cgi-bin/hgc?db=hg38&g=omimAvSnp&i={vid}&c=chr7&o={o}&t={t}'
 print('\\n###', vid, url)
 data=urllib.request.urlopen(url,timeout=30).read().decode('utf-8','ignore')
 for line in data.splitlines():
  if any(x in line for x in ['Amino', 'Allelic', 'dbSNP', 'ClinVar', 'OMIM', 'variant', 'replacement', 'title']):
   print(line[:500])
PY"

